(()=>{"use strict";class t{constructor(t){this.element=t,this.triggerBtn=this.element.querySelector("#collapse-trigger-btn"),this.contentWrapper=this.element.querySelector("#collapse-content-wrapper"),this.isCollapsed=!0}init(){this.triggerBtn.addEventListener("click",()=>this.toggle())}toggle(){if(this.isCollapsed){const t=this.contentWrapper.scrollHeight;this.contentWrapper.style.height=`${t}px`}else this.contentWrapper.style.height="0px";this.isCollapsed=!this.isCollapsed}}class e{constructor(t){this.element=t,this.triggerBtn=this.element.querySelector("#liker-trigger-btn"),this.sandbox=this.element.querySelector(".liker-sandbox-area")}init(){this.triggerBtn.addEventListener("click",()=>this.spawnHeart())}spawnHeart(){const t=document.createElement("img");t.src="pic/heart.png",t.className="floating-heart-element";const e=Math.floor(4*Math.random())+1;t.style.animation=`heart-path-${e} 500ms ease-out forwards`,this.sandbox.appendChild(t),t.addEventListener("animationend",()=>{t.remove()})}}class s{constructor(t){this.element=t,this.fabBtn=this.element.querySelector("#callback-toggle-fab-btn"),this.formCard=this.element.querySelector("#callback-form-card"),this.closeBtn=this.element.querySelector("#callback-close-form-btn")}init(){this.fabBtn.addEventListener("click",()=>{this.fabBtn.classList.add("hidden"),this.formCard.classList.remove("callback-card-hidden")}),this.closeBtn.addEventListener("click",()=>{this.formCard.classList.add("callback-card-hidden"),this.fabBtn.classList.remove("hidden")})}}document.addEventListener("DOMContentLoaded",()=>{const i=document.getElementById("collapse-widget-root");i&&new t(i).init();const n=document.getElementById("liker-widget-root");n&&new e(n).init();const r=document.getElementById("callback-widget-root");r&&new s(r).init()})})();